replacements.old:
summary(str) {
  if (str === undefined) return this._summary;
  this._summary = str;
  return this;
}

replacements.new:
summary(str) {
  if (str === undefined) return this._summary;
  this._summary = str;
  return this;
}

/**
 * Store usage examples (AgentCore R2 Extend reference).
 * @param {string} [text]
 * @return {(string[]|Command)}
 */
example(text) {
  if (!this._examples) this._examples = [];
  if (text === undefined) return this._examples;
  this._examples.push(text);
  return this;
}
